    "src/screens/ParentPortal.jsx": "import React, { useState } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { setChildId, updateInsights } from '../store/parentSlice.js';
import ParentDashboardForm from '../components/ParentDashboardForm.jsx';
import ProgressDisplay from '../components/ProgressDisplay.jsx';

function ParentPortal() {
  const dispatch = useDispatch();
  const { childId, insights } = useSelector((state) => state.parent);
  const authUser = useSelector((state) => state.auth.user);

  const [selectedChildName, setSelectedChildName] = useState('');

  // Dummy list of children for demonstration
  const dummyChildren = [
    { id: 'child1', name: 'Alice' },
    { id: 'child2', name: 'Bob' },
    { id: 'child3', name: 'Charlie' },
  ];

  // Handler to simulate fetching insights for a selected child
  const handleSelectChild = (id, name) => {
    dispatch(setChildId(id));
    setSelectedChildName(name);
    // In a real app, you would fetch actual data here based on childId
    // For now, dispatch some dummy insights
    dispatch(updateInsights({
      storyCompletion: Math.floor(Math.random() * 100) + 1,
      puzzleCompletion: Math.floor(Math.random() * 100) + 1,
      arcadeScore: Math.floor(Math.random() * 500) + 100,
      areasForImprovement: ['Reading Comprehension', 'Math Speed'],
      recentActivities: [
        { id: 1, type: 'story', title: 'The Magical Forest', date: '2023-10-26' },
        { id: 2, type: 'puzzle', title: 'Number Sequence', date: '2023-10-25' },
      ],
    }));
  };

  if (authUser?.role !== 'parent' && authUser?.role !== 'educator') {
    return <div className="text-center text-red-500 text-xl">Access Denied. Only Parents/Educators can view this portal.</div>;
  }

  return (
    <div className="p-8 bg-gradient-to-br from-cyan-100 to-blue-200 rounded-lg shadow-lg">
      <h1 className="text-4xl font-bold text-center text-blue-800 mb-8">Parent/Educator Portal</h1>
      <p className="text-lg text-center text-gray-700 mb-12">
        Gain valuable insights into your child's learning progress and manage settings.
      </p>

      <ParentDashboardForm 
        children={dummyChildren} 
        onSelectChild={handleSelectChild} 
        selectedChildId={childId}
      />

      {childId && insights ? (
        <div className="mt-12 bg-white p-6 rounded-lg shadow-md">
          <h2 className="text-3xl font-semibold text-blue-700 mb-6">Insights for {selectedChildName}</h2>

          <div className="mb-6">
            <p className="text-lg font-medium text-gray-700">Story World Completion:</p>
            <ProgressDisplay label="Stories" current={insights.storyCompletion} total={100} />
          </div>

          <div className="mb-6">
            <p className="text-lg font-medium text-gray-700">Puzzle Zone Completion:</p>
            <ProgressDisplay label="Puzzles" current={insights.puzzleCompletion} total={100} />
          </div>

          <div className="mb-6">
            <p className="text-lg font-medium text-gray-700">Learning Arcade High Score:</p>
            <p className="text-xl text-blue-600 font-bold">{insights.arcadeScore}</p>
          </div>

          <div className="mb-6">
            <h3 className="text-xl font-semibold text-gray-800 mb-3">Areas for Improvement:</h3>
            <ul className="list-disc list-inside text-gray-700">
              {insights.areasForImprovement.map((area, index) => (
                <li key={index}>{area}</li>
              ))}
            </ul>
          </div>

          <div>
            <h3 className="text-xl font-semibold text-gray-800 mb-3">Recent Activities:</h3>
            <ul className="list-disc list-inside text-gray-700">
              {insights.recentActivities.map((activity) => (
                <li key={activity.id}>{activity.type === 'story' ? 'Story:' : 'Puzzle:'} "{activity.title}" on {activity.date}</li>
              ))}
            </ul>
          </div>
        </div>
      ) : (
        <p className="text-center text-gray-600 mt-8 text-xl">Please select a child to view their progress.</p>
      )}
    </div>
  );
}

export default ParentPortal;",
