import React from 'react';
import { Routes, Route, Navigate } from 'react-router-dom';
import { useSelector } from 'react-redux';
import Navbar from './components/Navbar';
import Footer from './components/Footer';
import Dashboard from './screens/Dashboard';
import StoryWorld from './screens/StoryWorld';
import PuzzleZone from './screens/PuzzleZone';
import LearningArcade from './screens/LearningArcade';
import ProgressJournal from './screens/ProgressJournal';
import ParentPortal from './screens/ParentPortal';
import Profile from './screens/Profile';
import LoginForm from './components/LoginForm';
import RegisterForm from './components/RegisterForm';

function App() {
  const isAuthenticated = useSelector((state) => state.auth.isAuthenticated);
  const userRole = useSelector((state) => state.auth.user?.role);

  return (
    <div className="flex flex-col min-h-screen bg-gray-100">
      <Navbar />
      <main className="flex-grow container mx-auto px-4 py-8">
        <Routes>
          <Route path="/login" element={!isAuthenticated ? <LoginForm /> : <Navigate to="/dashboard" />} />
          <Route path="/register" element={!isAuthenticated ? <RegisterForm /> : <Navigate to="/dashboard" />} />

          {/* Protected Routes */}
          <Route
            path="/dashboard"
            element={isAuthenticated ? <Dashboard /> : <Navigate to="/login" />}
          />
          <Route
            path="/story-world"
            element={isAuthenticated ? <StoryWorld /> : <Navigate to="/login" />}
          />
          <Route
            path="/puzzle-zone"
            element={isAuthenticated ? <PuzzleZone /> : <Navigate to="/login" />}
          />
          <Route
            path="/learning-arcade"
            element={isAuthenticated ? <LearningArcade /> : <Navigate to="/login" />}
          />
          <Route
            path="/progress-journal"
            element={isAuthenticated ? <ProgressJournal /> : <Navigate to="/login" />}
          />
          <Route
            path="/profile"
            element={isAuthenticated ? <Profile /> : <Navigate to="/login" />}
          />

          {/* Parent/Educator Specific Route */}
          <Route
            path="/parent-portal"
            element={isAuthenticated && (userRole === 'parent' || userRole === 'educator') ? <ParentPortal /> : <Navigate to="/login" />}
          />

          <Route path="*" element={<Navigate to={isAuthenticated ? "/dashboard" : "/login"} />} />
        </Routes>
      </main>
      <Footer />
    </div>
  );
}

export default App;

