function PuzzleGame() {
  const dispatch = useDispatch();
  const [currentPuzzleIndex, setCurrentPuzzleIndex] = useState(0);
  const [selectedOption, setSelectedOption] = useState(null);
  const [feedback, setFeedback] = useState('');
  const [score, setScore] = useState(0);
  const [gameStarted, setGameStarted] = useState(false);
  const [gameOver, setGameOver] = useState(false);

  useEffect(() => {
    if (gameOver) {
      dispatch(updatePuzzleProgress({ solvedPuzzles: score, highestScore: score }));
    }
  }, [gameOver, score, dispatch]);

  const startNewGame = () => {
    setCurrentPuzzleIndex(0);
    setSelectedOption(null);
    setFeedback('');
    setScore(0);
    setGameStarted(true);
    setGameOver(false);
  };

  const handleOptionSelect = (option) => {
    if (!gameOver) {
      setSelectedOption(option);
    }
  };

  const handleSubmit = () => {
    if (!selectedOption) {
      setFeedback('Please select an option!');
      return;
    }

    const currentPuzzle = puzzles[currentPuzzleIndex];
    if (selectedOption === currentPuzzle.answer) {
      setFeedback('Correct! 🎉');
      setScore((prevScore) => prevScore + 1);
    } else {
      setFeedback(`Incorrect. The answer was ${currentPuzzle.answer}.`);
    }

    // Move to next puzzle after a short delay
    setTimeout(() => {
      setSelectedOption(null);
      setFeedback('');
      if (currentPuzzleIndex < puzzles.length - 1) {
        setCurrentPuzzleIndex((prevIndex) => prevIndex + 1);
      } else {
        setGameOver(true);
        setGameStarted(false);
      }
    }, 1500);
  };

  if (!gameStarted && !gameOver) {
    return (
      <div className="flex flex-col items-center justify-center p-6 bg-blue-50 rounded-lg border border-blue-200 shadow-md">
        <h3 className="text-2xl font-bold text-blue-700 mb-4">Ready for a Puzzle Challenge?</h3>
        <p className="text-gray-700 mb-6">Solve a series of fun puzzles to earn points!</p>
        <button
          onClick={startNewGame}
          className="px-6 py-3 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors shadow-md"
        >
          Start Puzzle Game
        </button>
      </div>
    );
  }

  if (gameOver) {
    return (
      <div className="flex flex-col items-center justify-center p-6 bg-green-50 rounded-lg border border-green-200 shadow-md">
        <h3 className="text-3xl font-bold text-green-700 mb-4">Game Over!</h3>
        <p className="text-xl text-gray-700 mb-6">You scored {score} out of {puzzles.length} puzzles!</p>
        <button
          onClick={startNewGame}
          className="px-6 py-3 bg-green-600 text-white rounded-lg hover:bg-green-700 transition-colors shadow-md"
        >
          Play Again
        </button>
      </div>
    );
  }

  const currentPuzzle = puzzles[currentPuzzleIndex];

  return (
    <div className="bg-white rounded-lg shadow-md p-6">
      <p className="text-sm text-gray-500 mb-2">Puzzle {currentPuzzleIndex + 1} of {puzzles.length}</p>
      <h4 className="text-xl font-semibold text-gray-800 mb-4">{currentPuzzle.question}</h4>
      <div className="space-y-3 mb-6">
        {currentPuzzle.options.map((option, index) => (
          <button
            key={index}
            onClick={() => handleOptionSelect(option)}
            className={`w-full text-left p-3 rounded-md border-2 
              ${selectedOption === option ? 'bg-blue-100 border-blue-500' : 'bg-gray-50 border-gray-200 hover:border-blue-300'}
              transition-colors duration-200`}
            disabled={feedback !== ''}
          >
            {option}
          </button>
        ))}
      </div>

      {feedback && (
        <p className={`mb-4 text-lg font-bold ${feedback.includes('Correct') ? 'text-green-600' : 'text-red-600'}`}>
          {feedback}
        </p>
      )}

      <button
        onClick={handleSubmit}
        className="w-full px-6 py-3 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors shadow-md"
        disabled={!selectedOption || feedback !== ''}
      >
        Submit Answer
      </button>
    </div>
  );
}

export default PuzzleGame;

