import React, { useState, useRef } from 'react';

function AvatarUploader({ currentAvatarUrl }) {
  const [avatarPreview, setAvatarPreview] = useState(currentAvatarUrl);
  const fileInputRef = useRef(null);

  const handleImageChange = (event) => {
    const file = event.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setAvatarPreview(reader.result);
        // In a real application, you would send `file` to a server here
        console.log('New avatar selected:', file.name);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleClick = () => {
    fileInputRef.current.click();
  };

  return (
    <div className="flex flex-col items-center p-4 bg-gray-50 rounded-lg shadow-inner">
      <input
        type="file"
        accept="image/*"
        ref={fileInputRef}
        onChange={handleImageChange}
        className="hidden"
      />
      <img
        src={avatarPreview}
        alt="Avatar Preview"
        className="w-32 h-32 rounded-full object-cover border-4 border-blue-400 cursor-pointer transition-transform hover:scale-105"
        onClick={handleClick}
      />
      <button
        onClick={handleClick}
        className="mt-4 px-5 py-2 bg-blue-600 text-white rounded-lg shadow-md hover:bg-blue-700 transition-colors"
      >
        Change Avatar
      </button>
      <p className="mt-2 text-sm text-gray-500">Click image or button to upload</p>
    </div>
  );
}

export default AvatarUploader;

