import React, { useState } from 'react';

function MultiplayerChallenge({ gameType }) {
  const [isSearching, setIsSearching] = useState(false);
  const [opponent, setOpponent] = useState(null);
  const [challengeActive, setChallengeActive] = useState(false);
  const [countdown, setCountdown] = useState(null);

  const startSearch = () => {
    setIsSearching(true);
    setOpponent(null);
    setChallengeActive(false);
    setCountdown(null);

    // Simulate matchmaking
    setTimeout(() => {
      const potentialOpponents = ['PlayerA', 'PlayerB', 'PlayerC', 'AI_Opponent'];
      const randomOpponent = potentialOpponents[Math.floor(Math.random() * potentialOpponents.length)];
      setOpponent(randomOpponent);
      setIsSearching(false);
      setCountdown(3);
      let count = 3;
      const timer = setInterval(() => {
        count--;
        if (count === 0) {
          clearInterval(timer);
          setChallengeActive(true);
          setCountdown(null);
          console.log(`Multiplayer ${gameType} challenge started with ${randomOpponent}`);
        } else {
          setCountdown(count);
        }
      }, 1000);
    }, 3000); // Simulate 3 seconds matchmaking time
  };

  const endChallenge = () => {
    setChallengeActive(false);
    setOpponent(null);
    setFeedback('Challenge ended. Well played!');
    setTimeout(() => setFeedback(''), 2000);
  };

  const [feedback, setFeedback] = useState('');

  return (
    <div className="bg-gray-50 p-6 rounded-lg shadow-md border border-gray-200 text-center">
      <h3 className="text-2xl font-bold text-gray-800 mb-4">Multiplayer {gameType === 'puzzle' ? 'Puzzle' : 'Arcade'} Challenge</h3>
      <p className="text-gray-600 mb-6">Compete safely with other players or smart AI opponents!</p>

      {!isSearching && !opponent && !challengeActive && (
        <button
          onClick={startSearch}
          className="px-6 py-3 bg-red-600 text-white rounded-lg hover:bg-red-700 transition-colors shadow-md"
        >
          Find Opponent
        </button>
      )}

      {isSearching && (
        <div className="flex flex-col items-center justify-center">
          <p className="text-lg text-red-500 font-semibold mb-3">Searching for opponent...</p>
          <div className="loader ease-linear rounded-full border-4 border-t-4 border-gray-200 h-12 w-12 mb-4"></div>
          <style jsx>{`
            .loader {
              border-top-color: #ef4444; /* red-500 */
              -webkit-animation: spinner 1.5s linear infinite;
              animation: spinner 1.5s linear infinite;
            }
            @-webkit-keyframes spinner {
              0% { -webkit-transform: rotate(0deg); }
              100% { -webkit-transform: rotate(360deg); }
            }
            @keyframes spinner {
              0% { transform: rotate(0deg); }
              100% { transform: rotate(360deg); }
            }
          `}</style>
        </div>
      )}

      {opponent && !challengeActive && countdown !== null && (
        <div className="mt-4">
          <p className="text-xl font-semibold text-green-700 mb-2">Opponent Found: {opponent}</p>
          <p className="text-4xl font-bold text-red-500">Starting in {countdown}...</p>
        </div>
      )}

      {challengeActive && opponent && (
        <div className="mt-4">
          <p className="text-2xl font-bold text-blue-700 mb-4">Challenge vs. {opponent} in progress!</p>
          <p className="text-lg text-gray-700">This is where the interactive {gameType} challenge would be rendered.</p>
          {/* Placeholder for actual game UI */}
          <div className="mt-6 p-4 bg-white border border-blue-200 rounded-lg">
            <p className="font-semibold text-blue-600">Game Board / Interface Here</p>
            <p className="text-sm text-gray-500 mt-2">Player 1: You</p>
            <p className="text-sm text-gray-500">Player 2: {opponent}</p>
            <button
              onClick={endChallenge}
              className="mt-6 px-5 py-2 bg-gray-500 text-white rounded-lg hover:bg-gray-600 transition-colors shadow-md"
            >
              End Challenge
            </button>
          </div>
        </div>
      )}
      {feedback && <p className="mt-4 text-green-600 font-semibold">{feedback}</p>}
    </div>
  );
}

export default MultiplayerChallenge;

