import React, { useState, useEffect } from 'react';

function ParentDashboardForm({ children, onSelectChild, selectedChildId }) {
  const [localSelectedChildId, setLocalSelectedChildId] = useState(selectedChildId || '');
  const [settings, setSettings] = useState({
    dailyLimit: '60',
    contentFilter: 'mild',
    notifications: true,
  });

  useEffect(() => {
    setLocalSelectedChildId(selectedChildId);
  }, [selectedChildId]);

  const handleChildChange = (e) => {
    const id = e.target.value;
    setLocalSelectedChildId(id);
    const childName = children.find(c => c.id === id)?.name || '';
    onSelectChild(id, childName);
  };

  const handleSettingChange = (e) => {
    const { name, value, type, checked } = e.target;
    setSettings((prevSettings) => ({
      ...prevSettings,
      [name]: type === 'checkbox' ? checked : value,
    }));
  };

  const handleSaveSettings = (e) => {
    e.preventDefault();
    console.log('Saving settings for child:', localSelectedChildId, settings);
    // In a real app, you would send these settings to a backend API
    alert('Settings saved successfully!');
  };

  return (
    <div className="bg-white p-6 rounded-lg shadow-md mb-8">
      <h2 className="text-2xl font-semibold text-blue-700 mb-4">Select Child & Manage Settings</h2>

      <div className="mb-6">
        <label htmlFor="child-select" className="block text-gray-700 text-sm font-bold mb-2">
          Select Child:
        </label>
        <select
          id="child-select"
          className="shadow border rounded w-full py-3 px-4 text-gray-700 leading-tight focus:outline-none focus:ring-2 focus:ring-blue-400 focus:border-transparent"
          value={localSelectedChildId}
          onChange={handleChildChange}
        >
          <option value="" disabled>-- Choose a child --</option>
          {children.map((child) => (
            <option key={child.id} value={child.id}>
              {child.name}
            </option>
          ))}
        </select>
      </div>

      {localSelectedChildId && (
        <form onSubmit={handleSaveSettings} className="mt-6">
          <h3 className="text-xl font-semibold text-gray-800 mb-4">Learning Settings for {children.find(c => c.id === localSelectedChildId)?.name}</h3>

          <div className="mb-5">
            <label htmlFor="dailyLimit" className="block text-gray-700 text-sm font-bold mb-2">Daily Screen Time Limit (minutes)</label>
            <input
              type="number"
              id="dailyLimit"
              name="dailyLimit"
              className="shadow appearance-none border rounded w-full py-3 px-4 text-gray-700 leading-tight focus:outline-none focus:ring-2 focus:ring-blue-400 focus:border-transparent"
              value={settings.dailyLimit}
              onChange={handleSettingChange}
              min="0"
              max="240"
            />
          </div>

          <div className="mb-5">
            <label htmlFor="contentFilter" className="block text-gray-700 text-sm font-bold mb-2">Content Filter Level</label>
            <select
              id="contentFilter"
              name="contentFilter"
              className="shadow border rounded w-full py-3 px-4 text-gray-700 leading-tight focus:outline-none focus:ring-2 focus:ring-blue-400 focus:border-transparent"
              value={settings.contentFilter}
              onChange={handleSettingChange}
            >
              <option value="mild">Mild (Ages 6+)</option>
              <option value="moderate">Moderate (Ages 9+)</option>
              <option value="advanced">Advanced (Ages 12+)</option>
            </select>
          </div>

          <div className="mb-6 flex items-center">
            <input
              type="checkbox"
              id="notifications"
              name="notifications"
              className="mr-2 h-4 w-4 text-blue-600 focus:ring-blue-500 border-gray-300 rounded"
              checked={settings.notifications}
              onChange={handleSettingChange}
            />
            <label htmlFor="notifications" className="text-gray-700 text-sm font-bold">Enable Email Notifications for Progress Reports</label>
          </div>

          <button
            type="submit"
            className="bg-blue-600 hover:bg-blue-700 text-white font-bold py-3 px-6 rounded-lg focus:outline-none focus:shadow-outline transition-colors w-full"
          >
            Save Settings
          </button>
        </form>
      )} 
    </div>
  );
}

export default ParentDashboardForm;
